"""Independent re-evaluation of a frozen design (design.json) against the project rules."""
import json, math
from cable import *
from model import *
from env import *
import nm
from opt import ka, tray_amp, raceway_amp, mat_ok, size_index, egc_base
D=json.load(open('/work/design.json'))
DES=D['circuits']; NTRAY=D['N_tray']
SI=lambda s: SIZES.index(s)
def db_occ():
    occ1={}; occ2={}
    for c in ('SE-1','F-10'):
        d=DES[c]
        for k in d['ducts']: occ1[k]=(c,d['mat'],SI(d['size']),CIRC[c]['load']/d['sets'])
    d=DES['F-05']
    for k in d['ducts']: occ2[k]=('F-05',d['mat'],SI(d['size']),CIRC['F-05']['load']/d['sets'])
    return occ1,occ2
OCC1,OCC2=db_occ()
R1=nm.db_ampacity('DB-1',OCC1); R2=nm.db_ampacity('DB-2',OCC2)
def ampacity(c,mat,i,sets=None,ducts=None):
    """corrected ampacity per set (after termination limit), and the uncapped corrected value"""
    if inst(c)=='RACEWAY': return raceway_amp(c,mat,i)
    if inst(c)=='TRAY': return tray_amp(c,mat,i,NTRAY)
    # duct bank: re-run NM with this conductor in this circuit's ducts, others as designed
    dbk='DB-1' if c in ('SE-1','F-10') else 'DB-2'
    occ=dict(OCC1 if dbk=='DB-1' else OCC2)
    s=DES[c]['sets'] if sets is None else sets
    dl=DES[c]['ducts'] if ducts is None else ducts
    for k in list(occ):
        if occ[k][0]==c: del occ[k]
    for k in dl[:s]: occ[k]=(c,mat,i,CIRC[c]['load']/s)
    r=nm.db_ampacity(dbk,occ)
    a=min(r[k]['amp'] for k in dl[:s])
    return min(a,MAT[mat]['RW%d'%term_temp(c)][i]), a
def amp_only_size(c,mat,sets):
    need=design_current(c)/sets; ms,nt=term_limits(c)
    for j in range(len(SIZES)):
        if not mat_ok(mat,j) or j>ms: continue
        if sets>1 and j<SI('1/0'): continue
        if inst(c)=='DUCT':
            a,_=ampacity(c,mat,j)
        else:
            a,_=ampacity(c,mat,j)
        if a>=need*1.0-1e-9: return j
    return None
def egc_required(c,mat,i,sets):
    base=SI(egc_base(CIRC[c]['ocpd'])); ao=amp_only_size(c,mat,sets)
    if ao is None or ao>=i: return base,ao
    return max(base,size_index(CMIL[base]*CMIL[i]/CMIL[ao])),ao
ROWS={}
for c in CIRC:
    d=CIRC[c]; s=DES[c]; i=SI(s['size']); mat=s['mat']; sets=s['sets']
    a,unc=ampacity(c,mat,i)
    vp,vd,R,X=vd_pct(c,mat,i,sets)
    ROWS[c]=dict(c=c,mat=mat,i=i,sets=sets,amp=a,amp_uncapped=unc,vd=vp,drop=vd,R=R,X=X)
# cumulative
def cum(c):
    up=UPSTREAM[c]
    return ROWS[c]['vd']+(cum(up) if up else 0.0)
for c in ROWS: ROWS[c]['cum']=cum(c)
if __name__=='__main__':
    for c in sorted(ROWS):
        r=ROWS[c]; e=egc_required(c,r['mat'],r['i'],r['sets'])
        print(c,r['mat'],SIZES[r['i']],r['sets'],'amp %.1f need %.2f'%(r['amp'],design_current(c)/r['sets']),'vd %.3f cum %.3f'%(r['vd'],r['cum']),'egc req',SIZES[e[0]],'have',DES[c]['egc'],'ampOnly',SIZES[e[1]] if e[1] is not None else None)
