ALLOWED_LARGE={SI(x) for x in ['4/0','300 kcmil','500 kcmil','600 kcmil']}
def check_size(c,mat,j,sets):
    """return list of failure reasons for using size j (same mat/sets) in place of the design, with the rest of the design fixed"""
    rs=[]
    ms,nt=term_limits(c)
    if not mat_ok(mat,j): rs.append('material (AL not permitted <#4)')
